<!doctype html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f172a"><link rel="manifest" href="/trainingapp/public/manifest.json"><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="/trainingapp/public/css/app.css"><title>FitTrack — Treningi</title></head>
<body class="bg-slate-50 text-slate-900"><main class="mx-auto max-w-3xl px-4 pb-28 pt-6 space-y-6"><header><a class="text-sm font-bold text-slate-500" href="/trainingapp/">← FitTrack</a><h1 class="mt-2 text-3xl font-black">Plany treningowe</h1><p class="mt-1 text-slate-500">Twórz zestawy ćwiczeń i uruchamiaj treningi.</p></header>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4"><h2 class="text-xl font-bold">Nowy plan</h2><form id="form" class="space-y-3"><label class="block text-sm font-semibold">Nazwa planu<input name="name" required maxlength="150" class="mt-1 w-full rounded-xl border p-3" placeholder="np. FBW A"></label><label class="block text-sm font-semibold">Opis<textarea name="description" class="mt-1 w-full rounded-xl border p-3" rows="2" placeholder="Opcjonalny opis"></textarea></label><div><div class="mb-2 flex items-center justify-between"><label class="text-sm font-semibold">Ćwiczenia</label><input id="search" class="w-1/2 rounded-xl border p-2 text-sm" placeholder="Szukaj ćwiczeń"></div><div id="exerciseList" class="max-h-72 space-y-2 overflow-auto rounded-xl border p-3">Ładowanie…</div></div><button class="w-full rounded-xl bg-slate-900 p-3 font-bold text-white">Utwórz plan</button><p id="notice" class="text-sm"></p></form></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><h2 class="text-xl font-bold">Zapisane plany</h2><div id="templates" class="space-y-3">Ładowanie…</div></section></main>
<nav class="fixed inset-x-0 bottom-0 z-40 border-t bg-white/95 backdrop-blur"><div class="mx-auto grid max-w-3xl grid-cols-5 text-center text-xs font-bold"><a class="p-3" href="/trainingapp/">⌂<br>Home</a><a class="p-3 text-slate-500" href="/trainingapp/calendar.php">▦<br>Kalendarz</a><a class="p-3" href="/trainingapp/workouts.php">◈<br>Treningi</a><a class="p-3 text-slate-500" href="/trainingapp/progress.php">↗<br>Progres</a><a class="p-3 text-slate-500" href="/trainingapp/nutrition.php">◉<br>Dieta</a></div></nav>
<script>
const API='/trainingapp/api';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){const r=await fetch(API+'/'+p,{headers:{'Content-Type':'application/json'},...o});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Błąd API');return d}
let exercises=[],templates=[];async function load(){[exercises,templates]=await Promise.all([api('exercises'),api('workout-templates')]);renderExercises();renderTemplates()}
function renderExercises(){const q=document.querySelector('#search').value.toLowerCase();const root=document.querySelector('#exerciseList');const list=exercises.filter(x=>(x.name+' '+(x.muscle_group||'')).toLowerCase().includes(q));root.innerHTML=list.map(x=>{const timed=x.exercise_type==='time';return '<div class="rounded-xl border p-3 space-y-3"><label class="flex items-center gap-3"><input class="exercise-check h-4 w-4" type="checkbox" value="'+x.id+'" data-type="'+esc(x.exercise_type)+'"><span class="flex-1"><span class="block font-semibold">'+esc(x.name)+'</span><span class="text-xs text-slate-500">'+esc(x.muscle_group||'Inne')+' · '+(timed?'czas':x.exercise_type==='bodyweight'?'masa ciała':'siłowe')+'</span></span></label><div class="grid grid-cols-3 gap-2"><label class="text-xs text-slate-500">Serie<input type="number" min="1" max="20" value="3" class="sets mt-1 w-full rounded-lg border p-2 text-sm"></label>'+(timed?'<label class="col-span-2 text-xs text-slate-500">Cel czasu (sek.)<input type="number" min="1" max="3600" value="45" class="duration mt-1 w-full rounded-lg border p-2 text-sm"></label>':'<label class="text-xs text-slate-500">Powt. min<input type="number" min="1" max="500" value="8" class="min-reps mt-1 w-full rounded-lg border p-2 text-sm"></label><label class="text-xs text-slate-500">Powt. max<input type="number" min="1" max="500" value="12" class="max-reps mt-1 w-full rounded-lg border p-2 text-sm"></label>')+'</div></div>'}).join('')||'<p class="text-sm text-slate-500">Brak ćwiczeń.</p>'}
function renderTemplates(){const root=document.querySelector('#templates');root.innerHTML=templates.map(t=>'<article class="rounded-2xl border p-4"><div class="flex items-start justify-between gap-3"><div><h3 class="text-lg font-bold">'+esc(t.name)+'</h3><p class="text-sm text-slate-500">'+esc(t.description||'Bez opisu')+'</p><p class="mt-2 text-sm">'+(t.exercises||[]).length+' ćwiczeń</p></div><button class="delete rounded-xl border px-3 py-2 text-sm" data-id="'+t.id+'">Archiwizuj</button></div><ol class="mt-3 list-inside list-decimal space-y-1 text-sm text-slate-600">'+(t.exercises||[]).map(x=>'<li>'+esc(x.exercise_name)+' — '+x.sets_count+' serii'+(x.min_reps?' × '+x.min_reps+(x.max_reps&&x.max_reps!==x.min_reps?'-'+x.max_reps:'')+' powt.':'')+'</li>').join('')+'</ol><a class="mt-4 inline-flex rounded-xl bg-slate-900 px-4 py-3 font-bold text-white" href="/trainingapp/workout.php?template_id='+t.id+'">Rozpocznij trening</a></article>').join('')||'<p class="text-slate-500">Nie masz jeszcze planów treningowych.</p>';root.querySelectorAll('.delete').forEach(b=>b.onclick=async()=>{if(!confirm('Zarchiwizować ten plan?'))return;try{await api('workout-templates/'+b.dataset.id,{method:'DELETE'});await load()}catch(e){alert(e.message)}})}
document.querySelector('#search').oninput=renderExercises;document.querySelector('#form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const chosen=[...document.querySelectorAll('.exercise-check:checked')].map(c=>{const row=c.closest('.rounded-xl.border');const timed=c.dataset.type==='time';return {exercise_id:Number(c.value),sets_count:Number(row.querySelector('.sets').value)||3,rest_seconds:90,min_reps:timed?Number(row.querySelector('.duration').value)||45:Number(row.querySelector('.min-reps').value)||8,max_reps:timed?Number(row.querySelector('.duration').value)||45:Number(row.querySelector('.max-reps').value)||12}});if(!chosen.length){document.querySelector('#notice').textContent='Wybierz przynajmniej jedno ćwiczenie.';return}try{await api('workout-templates',{method:'POST',body:JSON.stringify({name:f.get('name'),description:f.get('description'),exercises:chosen})});document.querySelector('#notice').textContent='Plan utworzony.';e.target.reset();await load()}catch(err){document.querySelector('#notice').textContent=err.message;document.querySelector('#notice').className='text-sm text-red-600'}};
load().catch(e=>{document.querySelector('#templates').textContent=e.message;document.querySelector('#exerciseList').textContent='Nie udało się pobrać ćwiczeń.'});
</script></body></html>